// AFMBP-2612 — the landing A/B's decide step, without a browser (fast; run it first).
//   1. The platform's assignment in ES5 (tools/xp/bolt-assign-es5.js, vendored from the
//      Experimentation platform session) answers the platform's own vectors exactly: the canonical
//      set (tools/xp/assignment-v1.json, pinned by sha256: the platform's
//      packages/shared/test-vectors/assignment-v1.json) and the set for this test's key and seed
//      (tools/xp/landing_demo_buttons.vectors.json, generated by the platform's assign()/bucket()).
//      All three fields per vector: the variation bucket, the traffic bucket and the arm.
//   2. Each /start/ page inlines those functions verbatim and the baked definition
//      (tools/xp/landing_demo_buttons.json) exactly.
//   3. The definition: before the bake (baked false) it is the SPEC's expected one, with the
//      placeholder configVersion 1 and the vector set pinned to it; after the bake (baked true) it
//      equals the post-Start public config committed in tools/xp/public-config-snapshot.json.
//   4. The page's decide script, run in a stub window: unbaked, a real visitor gets no arm; baked,
//      each vector's visitor gets its arm (and html.xp-t for treatment); ?bolt_xp=<variation> is
//      honoured only in a bolt_qa browser, kept for its session only, and leaves the address.
// Run: node tools/xp-assign-check.mjs
//      NC=<name> node tools/xp-assign-check.mjs   — one negative control (see NCS); each must FAIL.
import { readFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import vm from 'node:vm';

const NC = process.env.NC || '';
const ASSIGNMENT_V1_SHA256 = '8950b83ef461717f623a7d58974408f345aa9985fc414f03c9434ea4159e07f7';
const SPEC = { key: 'landing_demo_buttons', seed: 'landing-demo-v1', trafficPercentage: 100, variants: [{ key: 'control', allocation: 5000 }, { key: 'treatment', allocation: 5000 }] };
const PAGES = ['start/handyman.html', 'start/plumbing.html', 'start/general-contractor.html'];

const results = [];
const check = (name, ok, info) => { results.push({ name, ok: !!ok }); console.log(`  ${ok ? 'PASS' : 'FAIL'} ${name}${ok || info === undefined ? '' : ' ' + JSON.stringify(info)}`); };

// Negative controls: each breaks one input in memory; the run must then fail.
const NCS = {
  seed: 'the landing vectors checked with seed landing-demo-v2',
  fnv: 'the ES5 FNV prime changed (0x1b3 -> 0x1b5)',
  inline: 'one page inlines a changed assignment',
  def: 'one page bakes a different allocation (control 4000)',
  qa_gate: 'the page honours ?bolt_xp without bolt_qa',
  unbaked: 'the page assigns real visitors while unbaked',
};
if (NC && !NCS[NC]) { console.error(`unknown NC=${NC}; one of ${Object.keys(NCS).join(', ')}`); process.exit(2); }

let es5 = readFileSync('tools/xp/bolt-assign-es5.js', 'utf8');
if (NC === 'fnv') { const t = es5.replace(/0x1b3/g, '0x1b5'); if (t === es5) { console.error('NC fnv did not land'); process.exit(2); } es5 = t; }
const sandbox = { module: { exports: {} } };
vm.runInNewContext(es5, sandbox);
const { boltBucket, boltAssign } = sandbox.module.exports;

console.log('[the platform\'s vectors]');
const v1raw = readFileSync('tools/xp/assignment-v1.json');
check('assignment-v1.json is the platform\'s, byte for byte (sha256 pinned)', createHash('sha256').update(v1raw).digest('hex') === ASSIGNMENT_V1_SHA256);
const v1 = JSON.parse(v1raw.toString('utf8'));
const half = [{ key: 'control', allocation: 5000 }, { key: 'treatment', allocation: 5000 }];
const runSet = (label, set, seed) => {
  const exp = { key: set.experimentKey, seed, trafficPercentage: set.trafficPercentage ?? 100, variants: set.variants || half };
  let bad = 0;
  for (const v of set.vectors) {
    const base = `${v.subjectId}:${exp.key}:${exp.seed}:`;
    const got = { variationBucket: boltBucket(base + 'variation'), trafficBucket: boltBucket(base + 'traffic'), variation: boltAssign(v.subjectId, exp) };
    const ok = got.variationBucket === v.variationBucket && got.trafficBucket === v.trafficBucket && got.variation === v.variation;
    if (!ok) bad++;
    check(`${label} ${JSON.stringify(v.subjectId)}: buckets ${v.variationBucket}/${v.trafficBucket} -> ${v.variation}`, ok, got);
  }
  return bad;
};
runSet('assignment-v1', v1, v1.seed);
const v2 = JSON.parse(readFileSync('tools/xp/landing_demo_buttons.vectors.json', 'utf8'));
runSet('landing_demo_buttons', v2, NC === 'seed' ? 'landing-demo-v2' : v2.seed);
check('landing vectors: both arms present (5 control, 3 treatment)', v2.vectors.filter((v) => v.variation === 'control').length === 5 && v2.vectors.filter((v) => v.variation === 'treatment').length === 3);

console.log('[the baked definition]');
const def = JSON.parse(readFileSync('tools/xp/landing_demo_buttons.json', 'utf8'));
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const core = (d) => ({ key: d.key, seed: d.seed, trafficPercentage: d.trafficPercentage, variants: d.variants.map((x) => ({ key: x.key, allocation: x.allocation })) });
check('the vector set pins this definition (key, seed, traffic, arms in order)', same(core(def), core({ key: v2.experimentKey, seed: v2.seed, trafficPercentage: v2.trafficPercentage, variants: v2.variants })), core(def));
check('assignment unit: anonymous (the visitor, bolt_vid)', def.assignmentUnit === 'anonymous', def.assignmentUnit);
const attribution = readFileSync('attribution.js', 'utf8');
check('attribution.js accepts this key on sign-up links (XP_KEYS)', new RegExp(`var XP_KEYS = \\[[^\\]]*'${def.key}'`).test(attribution));
if (def.baked !== true) {
  check('NOT BAKED: the SPEC\'s expected definition', same(core(def), SPEC), core(def));
  check('NOT BAKED: configVersion is the placeholder 1 (QA links only)', def.configVersion === 1, def.configVersion);
  console.log('  NOTE the definition is not baked: every real visitor sees the sign-up card and nothing goes to the platform. Bake after Start: node tools/xp/bake.mjs');
} else {
  const snapPath = 'tools/xp/public-config-snapshot.json';
  check('BAKED: the post-Start public config snapshot is committed', existsSync(snapPath));
  const snap = existsSync(snapPath) ? JSON.parse(readFileSync(snapPath, 'utf8')) : { experiments: [] };
  const e = (snap.experiments || []).find((x) => x.key === def.key);
  check(`BAKED: the snapshot lists ${def.key}, running, for web`, e && e.status === 'running' && (e.platforms || []).includes('web'), e && { status: e.status, platforms: e.platforms });
  check('BAKED: key, seed, traffic and arms (order and allocations) equal the snapshot', e && same(core(def), core(e)), e && core(e));
  check('BAKED: assignment unit equals the snapshot', e && e.assignmentUnit === def.assignmentUnit, e && e.assignmentUnit);
  check('BAKED: configVersion is the snapshot\'s', Number.isInteger(def.configVersion) && def.configVersion >= 1 && def.configVersion === snap.configVersion, { def: def.configVersion, snap: snap.configVersion });
  check('BAKED: no platform overrides in the snapshot', e && Array.isArray(e.overrides) && e.overrides.length === 0, e && e.overrides);
}

console.log('[the pages]');
const fnBody = (s) => s.split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('if (typeof module')).join('\n');
const want = fnBody(readFileSync('tools/xp/bolt-assign-es5.js', 'utf8'));
for (const p of PAGES) {
  let html = readFileSync(p, 'utf8');
  if (NC === 'inline' && p === PAGES[0]) html = html.replace('return ((hi % 10000) * 7296 + (lo % 10000)) % 10000;', 'return ((hi % 10000) * 7297 + (lo % 10000)) % 10000;');
  if (NC === 'def' && p === PAGES[0]) html = html.replace('{"key":"control","allocation":5000}', '{"key":"control","allocation":4000}');
  const m = html.match(/<script>\n    \/\* The landing A\/B[\s\S]*?\(function \(\) \{\n      var XP = (\{.*\});\n([\s\S]*?)\n      var w = window/);
  check(`${p}: the decide script is the first script in <head>`, m && html.indexOf(m[0]) < html.indexOf('<script', html.indexOf(m[0]) + 10) && html.indexOf('<script') === html.indexOf(m[0]));
  if (!m) continue;
  check(`${p}: the assignment functions, verbatim`, fnBody(m[2]) === want);
  const baked = JSON.parse(m[1]);
  check(`${p}: the baked definition, exactly`, same(baked, { ...core(def), configVersion: def.configVersion, baked: def.baked }), baked);
}

console.log('[the decide script, in a stub window]');
const page0 = readFileSync(PAGES[0], 'utf8');
let decide = page0.match(/<script>\n    (\/\* The landing A\/B[\s\S]*?)\n  <\/script>/)[1];
if (NC === 'qa_gate') decide = decide.replace('        if (qa) {\n          forced = variant(f);', '        if (true) {\n          forced = variant(f);');
if (NC === 'unbaked') decide = decide.replace('(XP.baked ? boltAssign(vid, XP) : null)', 'boltAssign(vid, XP)');
const run = ({ search = '', vid = null, qa = null, sessionForce = null, bake = false }) => {
  const ls = new Map(), ss = new Map();
  if (vid) ls.set('bolt_vid', vid);
  if (qa) ls.set('bolt_qa', qa);
  if (sessionForce) ss.set('bolt_xp_force', sessionForce);
  const store = (m) => ({ getItem: (k) => (m.has(k) ? m.get(k) : null), setItem: (k, v) => m.set(k, String(v)), removeItem: (k) => m.delete(k) });
  const replaced = [];
  const win = {
    localStorage: store(ls), sessionStorage: store(ss),
    location: { search, pathname: '/start/handyman.html', hash: '' },
    history: { state: null, replaceState: (s, t, u) => replaced.push(u) },
    crypto: { randomUUID: () => '11111111-2222-4333-8444-555555555555' },
  };
  const doc = { documentElement: { className: '' } };
  let src = decide;
  if (bake) src = src.replace(/"configVersion":1,"baked":false\}/, '"configVersion":9,"baked":true}');
  vm.runInNewContext(src, { window: win, document: doc, Date, Math, RegExp, JSON, decodeURIComponent, unescape, encodeURIComponent });
  return { xp: win.boltXp, cls: doc.documentElement.className, ls, ss, replaced };
};
if (def.baked !== true) {
  const u = run({ vid: 'deadbeef-0000-4111-8222-333344445555' });
  check('unbaked: a real visitor (a treatment vector) gets no arm and the sign-up card', u.xp.variation === null && !u.cls.includes('xp-t'), u.xp);
}
for (const v of v2.vectors) {
  const r = run({ vid: v.subjectId, bake: true });
  check(`baked: ${v.subjectId} -> ${v.variation}${v.variation === 'treatment' ? ' (html.xp-t)' : ''}`, r.xp.variation === v.variation && r.xp.vid === v.subjectId && r.cls.includes('xp-t') === (v.variation === 'treatment'), { got: r.xp.variation, cls: r.cls });
}
const fresh = run({ bake: true });
check('first visit: the id is made here and kept as bolt_vid (attribution.js reads the same key)', fresh.xp.vid === '11111111-2222-4333-8444-555555555555' && fresh.ls.get('bolt_vid') === fresh.xp.vid);
const badVid = run({ vid: 'x', bake: true });
check('an invalid stored id is replaced', badVid.xp.vid === '11111111-2222-4333-8444-555555555555');
const qaF = run({ search: '?bolt_qa=1&bolt_xp=treatment&utm_source=fb', vid: '0b7f6c2e-5d1a-4c3b-9e8f-1a2b3c4d5e6f' });
check('QA ?bolt_xp=treatment: forced, kept for the session, the card is the demo card', qaF.xp.variation === 'treatment' && qaF.xp.forced === true && qaF.ss.get('bolt_xp_force') === 'treatment' && qaF.cls.includes('xp-t'), qaF.xp);
check('QA ?bolt_xp: taken out of the address, the rest kept', qaF.replaced.length === 1 && qaF.replaced[0] === '/start/handyman.html?bolt_qa=1&utm_source=fb', qaF.replaced);
const qaS = run({ qa: '1', sessionForce: 'control', vid: 'deadbeef-0000-4111-8222-333344445555', bake: true });
check('QA browser, later page of the session: the forced arm holds over the hashed one', qaS.xp.variation === 'control' && qaS.xp.forced === true, qaS.xp);
const qaOff = run({ search: '?bolt_qa=0&bolt_xp=treatment', qa: '1', vid: '0b7f6c2e-5d1a-4c3b-9e8f-1a2b3c4d5e6f', bake: true });
check('?bolt_qa=0 turns QA off first: ?bolt_xp is then ignored', qaOff.xp.forced === false && qaOff.xp.variation === 'control' && !qaOff.ss.has('bolt_xp_force'), qaOff.xp);
const nonQa = run({ search: '?bolt_xp=treatment', vid: '0b7f6c2e-5d1a-4c3b-9e8f-1a2b3c4d5e6f', bake: true });
check('a real visitor\'s ?bolt_xp is ignored: the hashed arm, nothing kept, out of the address', nonQa.xp.variation === 'control' && nonQa.xp.forced === false && !nonQa.ss.has('bolt_xp_force') && nonQa.replaced[0] === '/start/handyman.html', nonQa);
const qaBad = run({ search: '?bolt_qa=1&bolt_xp=bogus', vid: 'deadbeef-0000-4111-8222-333344445555', bake: true });
check('QA ?bolt_xp=<not an arm>: no force, the hashed arm', qaBad.xp.forced === false && qaBad.xp.variation === 'treatment', qaBad.xp);
const demoqa = run({ search: '?demoqa=1&bolt_xp=treatment', vid: '0b7f6c2e-5d1a-4c3b-9e8f-1a2b3c4d5e6f' });
check('?demoqa=1 counts as QA (as attribution.js reads it)', demoqa.xp.forced === true && demoqa.xp.variation === 'treatment', demoqa.xp);

const failed = results.filter((r) => !r.ok).length;
console.log(`\n${results.length} checks, ${failed} failed${NC ? ` (NC=${NC}: ${NCS[NC]}; expected to FAIL)` : ''}`);
process.exit(failed ? 1 : 0);
